css:
/* Benefit grid: a centred heading, then icon, title and text cards, five across. */
[data-bz-node="bg-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="benefit-grid"] .bz-block { padding-block: 0; }
[data-bz-section="benefit-grid"] h2 { margin: 0; text-align: center; font: 700 1.875rem / 1.2 var(--font-heading); color: #000; }
[data-bz-section="benefit-grid"] [data-bz-node="bg-row"] { margin-top: 55px; row-gap: 51px; grid-template-columns: repeat(5, minmax(0, 1fr)); }
[data-bz-section="benefit-grid"] [data-bz-node="bg-row"] > .bz-col { grid-column: auto; }
[data-bz-section="benefit-grid"] .bz-figure { margin: 0; display: flex; justify-content: center; align-items: center; height: 56px; }
[data-bz-section="benefit-grid"] .bz-figure img { width: auto; max-width: 100%; height: auto; border-radius: 0; }
[data-bz-section="benefit-grid"] h3 { margin: 24px 0 0; text-align: center; white-space: pre-line; font: 700 1.5rem / 1.18 var(--font-heading); color: var(--accent); letter-spacing: 0; }
[data-bz-section="benefit-grid"] [data-bz-node^="bg-desc"] .bz-text p { margin: 14px auto 0; text-align: center; font: 400 0.95rem / 1.46 var(--font-body); color: #333; max-width: 240px; }
@media (min-width: 1400px) { [data-bz-section="benefit-grid"] [data-bz-node^="bg-desc"] .bz-text p { white-space: pre-line; max-width: none; } }
@media (max-width: 1100px) { [data-bz-section="benefit-grid"] [data-bz-node="bg-row"] { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (max-width: 640px) { [data-bz-section="benefit-grid"] [data-bz-node="bg-row"] { grid-template-columns: repeat(2, minmax(0, 1fr)); } [data-bz-section="benefit-grid"] h2 { font-size: 1.5rem; } }
@media (max-width: 420px) { [data-bz-section="benefit-grid"] [data-bz-node="bg-row"] { grid-template-columns: 1fr; } }
